INSERT INTO invoices(invoice_number,room_id,resident_id,meter_reading_id,utility_rate_id,billing_cycle,rent_amount,water_amount,electric_amount,due_date)
 SELECT 'DF-202609-'||r.room_number,r.id,u.id,m.id,ur.id,'2026-09-01',r.rent_rate,(m.curr_water_unit-m.prev_water_unit)*ur.water_rate_per_unit,(m.curr_electric_unit-m.prev_electric_unit)*ur.electric_rate_per_unit,'2026-09-05'
 FROM rooms r JOIN users u ON u.student_id='6810301010' JOIN meter_readings m ON m.room_id=r.id AND m.billing_month='2026-09-01' JOIN utility_rates ur ON ur.effective_date='2026-08-01' WHERE r.id=11 ON CONFLICT DO NOTHING;
