INSERT INTO dorm_regulations(category,rule_title,rule_content,penalty_details) VALUES ('QUIET','ความสงบเรียบร้อยและเสียงดัง','Quiet Hours 22:00 น. – 07:00 น. ห้ามจัดปาร์ตี้หรือเปิดเพลงเสียงดัง','ตักเตือนเกิน 2 ครั้ง ปรับครั้งละ 500 บาท') ON CONFLICT DO NOTHING;
INSERT INTO dorm_regulations(category,rule_title,rule_content,penalty_details) VALUES ('WASTE','การทิ้งขยะและความสะอาด','ห้ามวางถุงขยะหน้าห้องพักเด็ดขาด มัดปากถุงทิ้งที่ห้องขยะชั้น 1 คัดแยกขยะรีไซเคิลและขยะเปียก','กรุณาปฏิบัติตามจุดคัดแยกขยะ') ON CONFLICT DO NOTHING;
INSERT INTO dorm_regulations(category,rule_title,rule_content,penalty_details) VALUES ('SAFETY','ข้อห้ามด้านความปลอดภัยและสัตว์เลี้ยง','ห้ามสูบบุหรี่และบุหรี่ไฟฟ้าทุกกรณี ไม่อนุญาตให้เลี้ยงสัตว์ ห้ามใช้เตาแก๊ส อนุญาตเตาไฟฟ้าและไมโครเวฟ','สูบบุหรี่หรือบุหรี่ไฟฟ้า ปรับ 2,000 บาท') ON CONFLICT DO NOTHING;
INSERT INTO dorm_regulations(category,rule_title,rule_content,penalty_details) VALUES ('ACCESS','การเข้า–ออก และผู้มาติดต่อ','ประตูคีย์การ์ดสแกน ผู้มาติดต่อแลกบัตรกับ รปภ. ห้ามผู้มาติดต่อค้างคืนเกิน 23:00 น. ที่จอดรถห้องละ 1 คัน','ผู้มาติดต่อออกจากหอพักก่อน 23:00 น.') ON CONFLICT DO NOTHING;
INSERT INTO dorm_regulations(category,rule_title,rule_content,penalty_details) VALUES ('BILLING','การชำระเงินและค่าน้ำค่าไฟ','ชำระวันที่ 1 – 5 ทุกเดือน ค้างชำระเกินวันที่ 10 ระงับคีย์การ์ดและตัดกระแสไฟฟ้าชั่วคราว','ปรับล่าช้าวันละ 100 บาท') ON CONFLICT DO NOTHING;
